js/smAgent.js:2226:                    githubTracker(effectiveRepoInfo.owner, effectiveRepoInfo.repo).postComment(ticket.prNumber, '🧵 Unresolved review threads — rework armed. This machine-authored PR is reviewed ' + '(ai_pr_reviewed) but still has open review threads. The rework leg owns open threads: ' + 'agent:rework is armed on this PR and the rework runner will work through the threads and push. ' + 'Validation re-runs automatically afterwards, and once the threads are resolved a fresh ' + 're-review is armed (review-threads-resolved).');
js/common/machineNotice.js:36:    '🧵 Unresolved review threads — rework armed.',
js/factory/review_verdict.js:341:        lines.push('### Unresolved review threads on PR #' + pr, '');

            // survive an APPROVE winner: the action probes the head's real
            // CI verdict (headHasRealFailure) and a red keeps agent:rework —
            // red-CI rework on a sticky-approved PR, the sticky dead-letter
            // issue arm and conflict-rework are not review losers. Convergent:
            // once the labels agree with the effective verdict the decision
            // is null and the tick moves on. Never fights the human review
            // state — only machine-owned label carriers reconcile, and PRs
            // without records fail open.
            try {
                if (DRY) {
                    console.log('  🧪 [dry] ' + key + ' would reconcile review verdicts on PR #' + ticket.prNumber);
                    processedKeys.push(key);
                    continue;
                }
                if (reconcileReviewVerdicts(effectiveRepoInfo, ticket,
                        verdictMachineLogins(effectiveConfig))) {
                    processedKeys.push(key);
                } else {
                    console.log('  ⏭️  ' + key + ' verdict records and labels already agree — nothing to reconcile');
                }
            } catch (e) {
                console.error('  ❌ reconcile_verdicts failed for ' + key + ': ' + (e.message || e));
            }
            continue;
        }

        if (rule.localAction === 'arm_rework') {
            // dmtools-agents #683 (live fa #1194/#1211/#1212 + dart #340,
            // 2026-10-04): machine-authored reviewed PRs with UNRESOLVED
            // review threads matched NO rule — every re-review armer
            // requires threadsResolved:true, its complement matched
            // nothing, and the 04:30 fa tick processed 0 of them. Owner
            // rule 2026-10-04: unresolved threads on a machine-authored
            // PR arm agent:rework — the rework leg owns open threads by
            // design (the note in review-stale-verdict-unchecked: its
            // threadsResolved guard "excludes the mid-rework window (the
            // rework leg owns open threads)"). Arm the PR label; the
            // rework-on-label rule dispatches the leg (issue-anchored with
            // the PR-anchored #544 fallback) and consumes the label — this
            // action never dispatches itself. Label FIRST, comment second:
            // the label is the functional bit (a lost comment costs
            // nothing — the leg still fires). Convergent: the rework
            // resolves the threads (review-threads-resolved then arms a
            // fresh review) or the label persists and this rule stays
            // quiet (notLabels agent:rework) — never both legs at once.
            // gh-806 AC1: one arm per (pr, head) — consult the in-flight
            // latch before labeling; a leg already flying owns the threads,
            // and re-arming it stacked 9 arms / 8 dead legs on fa #1428.
            if (consultReworkLatch(key, ticket, effectiveRepoInfo).latched) continue;
            // gh-917: the red-gate rule (rule.redHeadGated —
            // rework-on-red-gate-unlatched) arms rework on ANY machine-
            // authored red head, FIRST VALIDATION included — the same arm
            // path must carry the same anti-loop bound as fail_validation:
            // at redHeadCap (default 3) recorded reds on the UNCHANGED head
            // the arm is WITHHELD and the owner is escalated once per head
            // (no infinite retry on unfixable-without-toolchain
            // violations). priorReds reads the SAME 🔴 marker history
            // fail_validation writes (failMarkerState — one comment
            // fetch), so both arming paths share one per-head budget; a
            // head move resets it by construction (markers are head-keyed).
            // A read failure fails OPEN (empty history → arm): a broken
            // comment read must not strand a red head this gate exists to
            // un-stall.
            var redGated = rule.redHeadGated === true;
            var redGateHead = redGated
                ? ((ticket.pr && ticket.pr.headSha) || ticket.headSha) : null;
            var redGateMarks = redGated
                ? failMarkerState(effectiveRepoInfo, ticket.prNumber) : null;
            var redGatePrior = (redGated && redGateHead)
                ? (redGateMarks.redHeads[redGateHead] || 0) : 0;
            var redGateCap = redHeadCapOf(RUN_JOB_PARAMS);
            var redGateLine = (redGated && redGateHead)
                ? redHeadMarkerLine(redGatePrior, redGateHead, redGateCap) : null;
            try {
                if (DRY) {
                    console.log('  🧪 [dry] ' + key + ' would arm agent:rework (' +
                        (redGated ? 'red pre-merge gate, first validation included — gh-917' :
                         'unresolved review threads') + ' on PR #' + ticket.prNumber + ')');
                    processedKeys.push(key);
                    continue;
                }
                if (redGated && redGatePrior >= redGateCap) {
                    // Cap reached: withhold + escalate ONCE per head. The
                    // 🛑 marker in the escalation comment is the dedup —
                    // failMarkerState parsed it from the same fetch; a read
                    // failure above leaves reworkWithheld empty (re-post,
                    // fail toward visibility). Repeat ticks stay quiet (no
                    // processedKeys — suppressed decisions don't pollute
